const hasHealthRecords = `-- name: HasHealthRecords :one

SELECT EXISTS(
    SELECT 1 FROM dependent_health_records
    WHERE dependent_id = $1
) as has_records
`

// ============================================
// VALIDATION & UTILITIES
// ============================================
func (q *Queries) HasHealthRecords(ctx context.Context, dependentID pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, hasHealthRecords, dependentID)
	var has_records bool
	err := row.Scan(&has_records)
	return has_records, err
}

const updateDependentHealthRecord = `-- name: UpdateDependentHealthRecord :exec
UPDATE dependent_health_records
SET 
    record_type = COALESCE($2, record_type),
    weight_kg = COALESCE($3, weight_kg),
    height_cm = COALESCE($4, height_cm),
    head_circumference_cm = COALESCE($5, head_circumference_cm),
    temperature_c = COALESCE($6, temperature_c),
    notes = COALESCE($7, notes),
    next_appointment_date = COALESCE($8, next_appointment_date)
WHERE id = $1
`

type UpdateDependentHealthRecordParams struct {
	ID                  pgtype.UUID    `json:"id"`
	RecordType          pgtype.Text    `json:"record_type"`
	WeightKg            pgtype.Numeric `json:"weight_kg"`
	HeightCm            pgtype.Numeric `json:"height_cm"`
	HeadCircumferenceCm pgtype.Numeric `json:"head_circumference_cm"`
	TemperatureC        pgtype.Numeric `json:"temperature_c"`
	Notes               pgtype.Text    `json:"notes"`
	NextAppointmentDate pgtype.Date    `json:"next_appointment_date"`
}

func (q *Queries) UpdateDependentHealthRecord(ctx context.Context, arg UpdateDependentHealthRecordParams) error {
	_, err := q.db.Exec(ctx, updateDependentHealthRecord,
		arg.ID,
		arg.RecordType,
		arg.WeightKg,
		arg.HeightCm,
		arg.HeadCircumferenceCm,
		arg.TemperatureC,
		arg.Notes,
		arg.NextAppointmentDate,
	)
	return err
}

